import decimal
from functools import singledispatch

@singledispatch
def render(value):
    raise TypeError('unsupported')

@render.register(int)
def render_integer(value):
    return format(decimal.Decimal(int.__index__(value)), 'f')

@render.register(bool)
def render_boolean(value):
    return ('false', 'true')[value]

@render.register(list)
def render_list(value):
    return '['+','.join(map(render, value))+']'

