import json
from collections import defaultdict
from pathlib import Path

def terms(text):
    result = set()
    current = []
    for character in text:
        if 'A' <= character <= 'Z':
            current.append(chr(ord(character)+32))
        elif 'a' <= character <= 'z' or '0' <= character <= '9':
            current.append(character)
        else:
            if current:
                result.add(''.join(current))
                current = []
    if current:
        result.add(''.join(current))
    return result

class Index:
    def __init__(self):
        self.docs = {}
        self.postings = defaultdict(set)
    def put(self, key, text):
        self.delete(key)
        self.docs[key] = text
        for word in terms(text):
            self.postings[word].add(key)
    def delete(self, key):
        if key not in self.docs:
            return
        for word in terms(self.docs.pop(key)):
            group = self.postings[word]
            group.discard(key)
            if not group:
                del self.postings[word]
    def search(self, text):
        words = terms(text)
        if not words:
            return []
        answer = None
        for word in words:
            group = self.postings.get(word, set())
            answer = set(group) if answer is None else answer.intersection(group)
        return sorted(answer)
    def save(self, path):
        Path(path).write_text(json.dumps(self.docs, ensure_ascii=False, sort_keys=True), encoding='utf-8')
    @classmethod
    def load(cls, path):
        instance = cls()
        for key, text in json.loads(Path(path).read_text(encoding='utf-8')).items():
            instance.put(key, text)
        return instance

